import{_ as a,c as t,a3 as o,o as r}from"./chunks/framework.Ba5s4TxA.js";const h=JSON.parse('{"title":"主题","description":"","frontmatter":{},"headers":[],"relativePath":"theme.md","filePath":"theme.md"}'),c={name:"theme.md"};function n(d,e,i,f,l,s){return r(),t("div",null,e[0]||(e[0]=[o('<h1 id="主题" tabindex="-1">主题 <a class="header-anchor" href="#主题" aria-label="Permalink to &quot;主题&quot;">​</a></h1><h2 id="颜色" tabindex="-1">颜色 <a class="header-anchor" href="#颜色" aria-label="Permalink to &quot;颜色&quot;">​</a></h2><p>一个系统首先有一个背景色，在 Material Design 中被定义为 Surface。在国内主流应用中，一般是灰色系，比如<code>#F7F8FA</code>。</p><p>基于此，每个中性色组件应该有个区分 Surface 的背景色，叫作 Surface Container，而其上的文字与 Icon 的颜色则为 On Surface Container。（看 Material Design 中并没有提到这个角色，推测 Surface 和 Surface Container 颜色相近，属于一个派系，因此其上的字体共用一个值）</p><p>由此得出组件库的两个基本颜色：</p><ul><li><code>surface-container</code> 背景（light：<code>#ffffff</code>，dark：<code>#232324</code>）</li><li><code>on-surface</code> 文字和 Icon（light：<code>#1d2129</code>，dark：<code>#f6f6f6</code>）</li></ul>',6)]))}const p=a(c,[["render",n]]);export{h as __pageData,p as default};
